// === Tab: mySketch ===
let pg;
let theShader;

let dv = 3;
let size;

let tiles = [];

let colors = [
	["#F0F7EE", "#000000", "#FFF07C", "#5D737E"],
	["#0B3142", "#0F5257", "#9C92A3", "#C6B9CD"],
	["#000101", "#403F4C", "#F5E3E0", "#A9714B"],
	["#FFE946", "#A8C256", "#F65E86", "#246832"]
];

let palette;

let gap = 0.03;

let sides = [0, 1, 2, 3];
let shapes = [0, 1, 2, 3, 4];

function preload(){
	theShader = createShader(vert, frag);
}

function setup() {
	seed = random(500);

	palette = random(colors);

	dv = floor(random(8)+3);

    createCanvas(750, 750, WEBGL);
	background(0);

	size = width/dv;
	gap *= size;

	for(let i=0; i<dv*dv; i++){
		tiles.push(createGraphics(size, size));
		tiles[i].background(palette[1]);
		tiles[i].noStroke();
	}

    pg = createGraphics(width, height);
	pg.background(palette[0]);

	for(let i=0; i<dv; i++){
		for(let j=0; j<dv; j++){
			let chaos = randomGaussian(i/dv, 0.05);
			let sidesArr = shuffle(sides);
			let shapesArr = shuffle(shapes);

			for(let k=0; k<chaos*3-0.75; k++){
				pat(tiles[i*dv+j], palette[2+round(random())], sidesArr[k], shapesArr[k]);
			}

			pg.image(tiles[i*dv+j], j*size+gap, i*size+gap, size-2*gap, size-2*gap);
		}
	}
}

function draw() {
	shader(theShader);
	theShader.setUniform("u_resolution", [pg.width, pg.height]);
	theShader.setUniform("u_time", millis()/1000);
	theShader.setUniform("tex0", pg);
	let bg = color(palette[0]);
	theShader.setUniform("bg_col", [red(bg), green(bg), blue(bg)]);
	theShader.setUniform("seed", seed);

	quad(-1, -1, 1, -1, 1, 1, -1, 1);
}

function pat(gr, col, r, s){
	gr.push();
	gr.translate(gr.width/2, gr.height/2);
	gr.rotate(r*PI/2);
	gr.fill(col);

	//patterns
	switch (s){
		case 0:
			gr.rect(-gr.width/2, 0, gr.width, gr.height/2); //half square
			break;
		case 1:
			gr.triangle(-gr.width/2, 0, -gr.width/2, gr.height/2, gr.width/2, gr.height/2); //triangle
			break;
		case 2:
			gr.triangle(gr.width/2, 0, -gr.width/2, gr.height/2, gr.width/2, gr.height/2); //triangle (flipped)
			break;
		case 3:
			gr.circle(0, gr.height/2, gr.height); //big pie
			break;
		case 4:
			gr.circle(gr.width/2, gr.height/2, gr.height); //small pie
			break;
	}
	//patterns

	gr.pop();
}

const vert = `
attribute vec3 aPosition;
attribute vec2 aTexCoord;

void main() {
	vec4 positionVec4 = vec4(aPosition, 1.0);
	positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

	gl_Position = positionVec4;
}
`;

const frag = `
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;
uniform sampler2D tex0;
uniform vec3 bg_col;
uniform float seed;

//	Simplex 3D Noise 
//	by Ian McEwan, Ashima Arts
//
vec4 permute(vec4 x){return mod(((x*34.0)+1.0)*x, 289.0);}
vec4 taylorInvSqrt(vec4 r){return 1.79284291400159 - 0.85373472095314 * r;}

float snoise(vec3 v){ 
  const vec2  C = vec2(1.0/6.0, 1.0/3.0) ;
  const vec4  D = vec4(0.0, 0.5, 1.0, 2.0);

// First corner
  vec3 i  = floor(v + dot(v, C.yyy) );
  vec3 x0 =   v - i + dot(i, C.xxx) ;

// Other corners
  vec3 g = step(x0.yzx, x0.xyz);
  vec3 l = 1.0 - g;
  vec3 i1 = min( g.xyz, l.zxy );
  vec3 i2 = max( g.xyz, l.zxy );

  //  x0 = x0 - 0. + 0.0 * C 
  vec3 x1 = x0 - i1 + 1.0 * C.xxx;
  vec3 x2 = x0 - i2 + 2.0 * C.xxx;
  vec3 x3 = x0 - 1. + 3.0 * C.xxx;

// Permutations
  i = mod(i, 289.0 ); 
  vec4 p = permute( permute( permute( 
             i.z + vec4(0.0, i1.z, i2.z, 1.0 ))
           + i.y + vec4(0.0, i1.y, i2.y, 1.0 )) 
           + i.x + vec4(0.0, i1.x, i2.x, 1.0 ));

// Gradients
// ( N*N points uniformly over a square, mapped onto an octahedron.)
  float n_ = 1.0/7.0; // N=7
  vec3  ns = n_ * D.wyz - D.xzx;

  vec4 j = p - 49.0 * floor(p * ns.z *ns.z);  //  mod(p,N*N)

  vec4 x_ = floor(j * ns.z);
  vec4 y_ = floor(j - 7.0 * x_ );    // mod(j,N)

  vec4 x = x_ *ns.x + ns.yyyy;
  vec4 y = y_ *ns.x + ns.yyyy;
  vec4 h = 1.0 - abs(x) - abs(y);

  vec4 b0 = vec4( x.xy, y.xy );
  vec4 b1 = vec4( x.zw, y.zw );

  vec4 s0 = floor(b0)*2.0 + 1.0;
  vec4 s1 = floor(b1)*2.0 + 1.0;
  vec4 sh = -step(h, vec4(0.0));

  vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy ;
  vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww ;

  vec3 p0 = vec3(a0.xy,h.x);
  vec3 p1 = vec3(a0.zw,h.y);
  vec3 p2 = vec3(a1.xy,h.z);
  vec3 p3 = vec3(a1.zw,h.w);

//Normalise gradients
  vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
  p0 *= norm.x;
  p1 *= norm.y;
  p2 *= norm.z;
  p3 *= norm.w;

// Mix final noise value
  vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
  m = m * m;
  return 42.0 * dot( m*m, vec4( dot(p0,x0), dot(p1,x1), 
                                dot(p2,x2), dot(p3,x3) ) );
}

void main(){
	float px = 1./u_resolution.y; //pixel height

	vec3 bg_normal = bg_col/256.; //normalize the color

	vec2 uv = gl_FragCoord.xy/u_resolution;
	uv*=0.5;
	uv.y = 1.-uv.y;

	vec4 tex = texture2D(tex0,vec2(uv.x, uv.y));

	vec3 tex_col = tex.rgb;

	float edge = 0.4;
	vec3 col = mix(tex_col, bg_normal, 
		smoothstep(edge, edge+px, 
			snoise(vec3((uv.x+uv.y*0.6)*60., uv.y*5., seed))*
			snoise(vec3(uv*2.5, seed))+
			snoise(vec3((vec2(1.)-uv)*200., seed))*0.25
		)
		);

	gl_FragColor = vec4(col, 1.0);
}`

